INSERT INTO arelore_education.user_detection_type
(type_code, type_name, type_description, extra_info)
VALUES
    ('RK_SYSANAL_2016H1_JC', '软考-系统分析师-2016年上半年-综合知识', '全国计算机技术与软件专业技术资格（水平）考试 系统分析师（高级） 2016年上半年 综合知识（来源：2016年上半年 系统分析师 详细答案.docx）', '{"source":"2016年上半年 系统分析师 详细答案.docx","exam":"系统分析师","year":"2016","term":"上半年","session":"综合知识","questionCount":43,"objectiveCount":43,"subjectiveCount":0,"resultMeanings":{},"scoring":{"resultMode":"objective_sum","scoreDimension":"score","maxScore":43,"scoringVersion":"1.0"}}')
ON DUPLICATE KEY UPDATE
                     type_name = VALUES(type_name),
                     type_description = VALUES(type_description),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SYSANAL_2016H1_JC', 'RK_SYSANAL_2016H1_JC_Q003', 'A
【解析】本题考查UML图
UML对系统架构的定义是系统的组织结构，包括系统分解的组成部分，以及它们的关联性、交互机制和指导原则等提供系统设计的信息。具体来说，就是指以下5个系统视图：
(1)逻辑视图。逻辑视图也称为设计视图，它表示了设计模型中在架构方面具有重要意义的部分，即类、子系统、包和用例实现的子集。
(2)进程视图。进程视图是可执行线程和进程作为活动类的建模，它是逻辑视图的一次执行实例，描述了并发与同步结构。
(3)实现视图。实现视图对组成基于系统的物理代码的文件和构件进行建模。
(4)部署视…', 3, '单选题', '[{"key":"A","text":"泛化关系","scores":{"score":0}},{"key":"B","text":"关联关系","scores":{"score":0}},{"key":"C","text":"包含关系","scores":{"score":1}},{"key":"D","text":"组合关系","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":3,"imageHashValues":[],"correctOptionKey":"C","fullQuestionName":"A\\n【解析】本题考查UML图\\nUML对系统架构的定义是系统的组织结构，包括系统分解的组成部分，以及它们的关联性、交互机制和指导原则等提供系统设计的信息。具体来说，就是指以下5个系统视图：\\n(1)逻辑视图。逻辑视图也称为设计视图，它表示了设计模型中在架构方面具有重要意义的部分，即类、子系统、包和用例实现的子集。\\n(2)进程视图。进程视图是可执行线程和进程作为活动类的建模，它是逻辑视图的一次执行实例，描述了并发与同步结构。\\n(3)实现视图。实现视图对组成基于系统的物理代码的文件和构件进行建模。\\n(4)部署视图。部署视图把构件部署到一组物理节点上，表示软件到硬件的映射和分布结构。\\n(5)用例视图。用例视图是最基本的需求分析模型。\\n\\n2016年5月第3、4题\\nUML 事物的关系中，(3)和(4)本质上都属于依赖关系。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

